def methodology() -> str:
    return f'''<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Методология финансовых материалов — Кубыш</title><meta name="description" content="Как команда Кубыша готовит материалы о личных финансах: источники, расчёты, обновления, границы образовательного контента."><meta name="robots" content="index,follow"><link rel="canonical" href="https://kubysh.com/metodologiya/"><link rel="stylesheet" href="/assets/seo.css?v=20260915a"><script defer src="/assets/seo.js?v=20260915a"></script></head><body><header><div class="wrap top"><a class="logo" href="/">Кубы<span>ш</span></a><nav class="topnav"><a class="hub" href="/lichnye-finansy/">Личные финансы</a><a class="install js-appstore" href="{APP_STORE}">Установить</a></nav></div></header><main class="wrap"><nav class="crumbs"><a href="/">Кубыш</a> → Методология</nav><h1>Как мы готовим материалы о личных финансах</h1><p class="lead">Финансы относятся к темам, где красивый совет может дорого стоить. Поэтому мы отделяем проверяемую арифметику и общую финансовую грамотность от персональных решений.</p><h2>Принципы</h2><ol><li><strong>Пишем под задачу человека.</strong> Разные поисковые интенты получают отдельные материалы, но мы не создаём страницы только ради перестановки ключевых слов.</li><li><strong>Показываем формулу.</strong> Если есть расчёт, из текста должно быть понятно, из каких чисел он получился.</li><li><strong>Не обещаем доходность.</strong> Калькуляторы накоплений по умолчанию считают собственные взносы без выдуманной инвестиционной доходности.</li><li><strong>Ссылаемся на первичные и профильные источники.</strong> Для общей финансовой грамотности используем в том числе материалы Банка России и проекта «Финансовая культура».</li><li><strong>Обновляем при изменении продукта или правил.</strong> На материалах стоит дата обновления.</li></ol><h2>Граница материала</h2><p>Статьи и калькуляторы на kubysh.com — образовательный контент. Они не учитывают все обстоятельства конкретного человека и не являются индивидуальной инвестиционной, кредитной, налоговой или юридической рекомендацией.</p><h2>О продукте</h2><p>Кубыш — приложение для планирования денег между доходами: оно учитывает обязательные платежи, цели и фактические траты и пересчитывает доступную сумму после изменений. Для базового сценария не требуется доступ к банковскому счёту.</p><h2>Источники</h2><ul class="sources">{''.join(f'<li><a href="{u}" rel="noopener">{html.escape(n)}</a></li>' for n,u in SOURCES)}</ul><p class="updated">Последнее обновление: {DATE}</p></main><footer><div class="wrap"><div class="links"><a href="/lichnye-finansy/">Все гайды</a><a href="/privacy/">Политика ПД</a><a href="/terms/">Соглашение</a></div>© Кубыш</div></footer></body></html>'''


def sitemap() -> str:
    urls = ["", "lichnye-finansy", *PAGES.keys(), "metodologiya", "skolko-mozhno-tratit", "finansovaya-podushka", "alternativa-dzen-mani", "privacy", "terms"]
    unique=[]
    for u in urls:
        if u not in unique: unique.append(u)
    rows=[]
    for slug in unique:
        loc="https://kubysh.com/" + (f"{slug}/" if slug else "")
        pr="1.0" if slug=="" else ("0.9" if slug=="lichnye-finansy" else "0.7")
        rows.append(f"  <url><loc>{loc}</loc><lastmod>{DATE}</lastmod><changefreq>monthly</changefreq><priority>{pr}</priority></url>")
    return '<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n'+"\n".join(rows)+'\n</urlset>\n'


